import React, { useState } from 'react';
import { CGuide, Link, CTable, Grid } from '@cloud-materials/common';
import type { CGuideStepProps } from '../interface';

const CGuideFoldButton = CGuide.CGuideFoldButton;

type DataItemType = {
  name: string;
  salary: number;
  address: string;
  email: string;
};

const getData = (pageNumber = 1, pageSize = 10): Promise<{ data: DataItemType[]; total: number }> => {
  const res = {
    data: Array.from({ length: pageSize }).map((_, index) => ({
      key: `${pageNumber}_${index}`,
      name: `William Smith_${pageNumber}_${index}`,
      salary: 23000 + index * 1000,
      address: `${pageNumber}_${index} Park Road, London`,
      email: `william.smith_${pageNumber}_${index}@example.com`,
    })),
    total: 100,
  };
  return new Promise(resolve => {
    setTimeout(() => {
      resolve(res);
    }, 1000);
  });
};

